            check(call("POST","/api/enrollments",map("label","bad limits","maxUses",EnrollmentRegistry.MAX_USES_PER_CODE+1),true,null)[0].equals(400),"enrollment bounded");
            Map issued=issue(2);String code=(String)issued.get("enrollmentToken"),enrollmentId=(String)((Map)issued.get("enrollment")).get("id");
            check(call("POST","/api/agent/register",registration("fixture-install-01"),false,"invalid")[0].equals(401),"invalid enrollment rejected");
            Map first=ok(call("POST","/api/agent/register",registration("fixture-install-01"),false,code),200,"first register"),second=ok(call("POST","/api/agent/register",registration("fixture-install-02"),false,code),200,"second register");
            String h1=(String)first.get("hostId"),h2=(String)second.get("hostId"),t1=(String)first.get("agentToken"),t2=(String)second.get("agentToken");check(!h1.equals(h2)&&!t1.equals(t2),"unique identity and credentials despite shared hostname");
            Map replay=ok(call("POST","/api/agent/register",registration("fixture-install-01"),false,code),200,"retry after consumed code");check(t1.equals(replay.get("agentToken"))&&h1.equals(replay.get("hostId")),"stable registration replay");
            check(call("POST","/api/agent/register",registration("fixture-install-03"),false,code)[0].equals(409),"max uses enforced");
            Map alternate=issue(1);check(call("POST","/api/agent/register",registration("fixture-install-01"),false,(String)alternate.get("enrollmentToken"))[0].equals(409),"identity not silently rebound to another code");
            check(((List)view().get("hosts")).size()==3,"legacy preserved plus two identities");check(((Number)((Map)((List)view().get("enrollments")).get(1)).get("usedCount")).intValue()==2,"retry consumes no extra use");
            ok(call("POST","/api/agent/heartbeat",map("hostId","fixture-host","hostname","legacy","javaVersion","fixture"),false,"fixture-agent-token"),200,"legacy credential migrated");
            check(call("GET","/api/agent/poll?hostId="+h2,null,false,t1)[0].equals(403),"cross-host poll blocked");check(call("POST","/api/agent/heartbeat",map("hostId",h2),false,t1)[0].equals(403),"cross-host heartbeat blocked");check(call("GET","/api/agent/settings?hostId="+h2,null,false,t1)[0].equals(403),"cross-host settings blocked");
